"""A small, dependency-free client for OpenAI's Responses API.

The module deliberately does not log prompts, API keys, or response bodies.
Responses are requested with ``store: false`` by default.  That controls API
storage, but is not a substitute for reviewing OpenAI's data/privacy terms for
your account before sending sensitive information.

Example:

    from openai_client import send_prompt

    answer = send_prompt("Write a haiku about rain.")
    print(answer)

Set OPENAI_API_KEY in the environment, or pass api_key= explicitly.
"""

from __future__ import annotations

import argparse
import json
import os
import sys
from dataclasses import dataclass
from typing import Any, Mapping, Optional
from urllib import error, request


RESPONSES_URL = "https://api.openai.com/v1/responses"


@dataclass
class OpenAIAPIError(RuntimeError):
    """An error response returned by the OpenAI API."""

    status_code: int
    message: str
    body: Optional[Mapping[str, Any]] = None

    def __str__(self) -> str:
        return "OpenAI API error {}: {}".format(self.status_code, self.message)


def create_response(
    prompt: str,
    *,
    model: str = "gpt-4.1-mini",
    instructions: Optional[str] = None,
    api_key: Optional[str] = None,
    timeout: float = 60,
    store: bool = False,
    max_output_tokens: Optional[int] = None,
) -> dict[str, Any]:
    """Send one text prompt and return the complete Responses API object.

    ``api_key`` takes precedence over the ``OPENAI_API_KEY`` environment
    variable.  It is used only for this request and is never written to disk.
    Set ``store=True`` only if you intentionally want API-side storage.
    """
    if not isinstance(prompt, str) or not prompt:
        raise ValueError("prompt must be a non-empty string")
    if not isinstance(model, str) or not model:
        raise ValueError("model must be a non-empty string")
    if timeout <= 0:
        raise ValueError("timeout must be positive")

    secret = api_key or os.environ.get("OPENAI_API_KEY")
    if not secret:
        raise ValueError("provide api_key or set OPENAI_API_KEY")

    payload: dict[str, Any] = {
        "model": model,
        "input": prompt,
        "store": store,
    }
    if instructions is not None:
        payload["instructions"] = instructions
    if max_output_tokens is not None:
        if max_output_tokens <= 0:
            raise ValueError("max_output_tokens must be positive")
        payload["max_output_tokens"] = max_output_tokens

    data = json.dumps(payload).encode("utf-8")
    http_request = request.Request(
        RESPONSES_URL,
        data=data,
        headers={
            "Authorization": "Bearer " + secret,
            "Content-Type": "application/json",
            "Accept": "application/json",
        },
        method="POST",
    )

    try:
        with request.urlopen(http_request, timeout=timeout) as http_response:
            return _decode_json(http_response.read(), http_response.status)
    except error.HTTPError as exc:
        parsed = _try_decode_json(exc.read())
        message = _error_message(parsed) or exc.reason
        raise OpenAIAPIError(exc.code, str(message), parsed) from exc
    except error.URLError as exc:
        raise ConnectionError("could not reach the OpenAI API: {}".format(exc.reason)) from exc


def send_prompt(prompt: str, **kwargs: Any) -> str:
    """Send one prompt and return the API's text output.

    Raises ``ValueError`` if the response has no text output.  Use
    ``create_response`` when you need the original structured response.
    """
    return response_text(create_response(prompt, **kwargs))


def response_text(response: Mapping[str, Any]) -> str:
    """Extract all text from a Responses API response object."""
    direct_text = response.get("output_text")
    if isinstance(direct_text, str):
        return direct_text

    pieces: list[str] = []
    for item in response.get("output", []):
        if not isinstance(item, Mapping) or item.get("type") != "message":
            continue
        for content in item.get("content", []):
            if not isinstance(content, Mapping):
                continue
            if content.get("type") in {"output_text", "text"}:
                text = content.get("text")
                if isinstance(text, str):
                    pieces.append(text)
    if pieces:
        return "".join(pieces)
    raise ValueError("the response did not contain text output")


def _decode_json(data: bytes, status_code: int) -> dict[str, Any]:
    parsed = _try_decode_json(data)
    if not isinstance(parsed, dict):
        raise OpenAIAPIError(status_code, "API returned invalid JSON")
    return parsed


def _try_decode_json(data: bytes) -> Optional[dict[str, Any]]:
    try:
        parsed = json.loads(data.decode("utf-8"))
    except (UnicodeDecodeError, json.JSONDecodeError):
        return None
    return parsed if isinstance(parsed, dict) else None


def _error_message(body: Optional[Mapping[str, Any]]) -> Optional[str]:
    if isinstance(body, Mapping):
        api_error = body.get("error")
        if isinstance(api_error, Mapping) and isinstance(api_error.get("message"), str):
            return api_error["message"]
    return None


def _main() -> int:
    parser = argparse.ArgumentParser(description="Send a text prompt to OpenAI's Responses API.")
    parser.add_argument("prompt", help="text to send")
    parser.add_argument("--model", default="gpt-4.1-mini")
    parser.add_argument("--instructions")
    parser.add_argument("--timeout", type=float, default=60)
    parser.add_argument("--max-output-tokens", type=int)
    args = parser.parse_args()
    try:
        print(send_prompt(
            args.prompt,
            model=args.model,
            instructions=args.instructions,
            timeout=args.timeout,
            max_output_tokens=args.max_output_tokens,
        ))
    except (ConnectionError, OpenAIAPIError, ValueError) as exc:
        print(str(exc), file=sys.stderr)
        return 1
    return 0


if __name__ == "__main__":
    raise SystemExit(_main())
